package com.anssa8bu.ssafy.event.application; import com.anssa8bu.ssafy.event.config.OutboxProperties; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; @Component public class OutboxScheduler {private final OutboxPublishService publish;private final OutboxClaimService claim;private final OutboxProperties props;public OutboxScheduler(OutboxPublishService p,OutboxClaimService c,OutboxProperties props){publish=p;claim=c;this.props=props;}@Scheduled(fixedDelayString="${app.outbox.fixed-delay:1s}")public void run(){if(!props.enabled())return;claim.recoverExpired();publish.publishBatch();}}
